package service

import (
	"strconv"
	"time"

	"lms/backend/internal/models"
)

// 本文件集中放置纯业务规则判定函数，无 I/O 依赖，便于单元测试与复用（高内聚）。

const dateLayout = "2006-01-02"

// checkBorrow 判定是否允许借阅：库存、在借上限、逾期三个条件。
func checkBorrow(available, activeCount, overdueCount int) error {
	switch {
	case available <= 0:
		return Error("该图书暂无在馆库存")
	case activeCount >= MaxBorrow:
		return Error("在借图书已达上限（5 本），请先归还")
	case overdueCount > 0:
		return Error("您有逾期未还的图书，请先归还后再借阅")
	}
	return nil
}

// checkRenew 判定是否允许续借：续借次数与是否逾期。
func checkRenew(renewCount int, dueDate, today string) error {
	switch {
	case renewCount >= MaxRenew:
		return Error("该图书已续借 1 次，无法再次续借")
	case dueDate < today:
		return Error("图书已逾期，无法续借，请先归还")
	}
	return nil
}

// checkTotalQty 判定修改馆藏数量时不能小于已借出数量。
func checkTotalQty(totalQty, borrowed int) error {
	if totalQty < borrowed {
		return Error("馆藏数量不能小于当前已借出数量")
	}
	return nil
}

// calcFine 按应还日期与实际归还日期计算逾期罚款；未逾期为 0。
func calcFine(dueDate, returnDate string) float64 {
	due, err1 := time.Parse(dateLayout, dueDate)
	ret, err2 := time.Parse(dateLayout, returnDate)
	if err1 != nil || err2 != nil {
		return 0
	}
	if !ret.After(due) {
		return 0
	}
	return float64(ret.Sub(due).Hours()/24) * FinePerDay
}

// stateText 根据状态与应还日期动态生成借阅状态文本。
func stateText(rec models.BorrowRecord, today time.Time) string {
	if rec.Status == "returned" {
		return "已归还"
	}
	due, err := time.Parse(dateLayout, rec.DueDate)
	if err != nil {
		return rec.Status
	}
	// 按日历日计算差值（统一取当天零点），避免当天时刻导致天数少算
	nowDay := time.Date(today.Year(), today.Month(), today.Day(), 0, 0, 0, 0, time.Local)
	dueDay := time.Date(due.Year(), due.Month(), due.Day(), 0, 0, 0, 0, time.Local)
	days := int(dueDay.Sub(nowDay).Hours() / 24)
	if days < 0 {
		return "已逾期 " + strconv.Itoa(-days) + " 天"
	}
	return "借阅中（剩 " + strconv.Itoa(days) + " 天）"
}

// annotate 为借阅记录批量填充动态状态字段。
func annotate(recs []models.BorrowRecord) []models.BorrowRecord {
	today := time.Now()
	for i := range recs {
		recs[i].State = stateText(recs[i], today)
	}
	return recs
}

package service

import (
	"testing"
	"time"

	"lms/backend/internal/models"
)

// 第一轮：纯业务规则单元测试（无 I/O 依赖）。

func TestCheckBorrow(t *testing.T) {
	cases := []struct {
		name              string
		available, active, overdue int
		wantErr           bool
	}{
		{"全部满足", 3, 2, 0, false},
		{"无库存", 0, 0, 0, true},
		{"达到上限", 3, 5, 0, true},
		{"存在逾期", 3, 1, 1, true},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			err := checkBorrow(c.available, c.active, c.overdue)
			if (err != nil) != c.wantErr {
				t.Fatalf("期望错误=%v，实际=%v", c.wantErr, err)
			}
		})
	}
}

func TestCheckRenew(t *testing.T) {
	today := time.Now().Format(dateLayout)
	future := time.Now().AddDate(0, 0, 10).Format(dateLayout)
	past := time.Now().AddDate(0, 0, -2).Format(dateLayout)

	if err := checkRenew(0, future, today); err != nil {
		t.Fatalf("正常续借应通过，实际=%v", err)
	}
	if err := checkRenew(1, future, today); err == nil {
		t.Fatal("续借次数超限应拒绝")
	}
	if err := checkRenew(0, past, today); err == nil {
		t.Fatal("逾期图书续借应拒绝")
	}
}

func TestCheckTotalQty(t *testing.T) {
	if err := checkTotalQty(5, 3); err != nil {
		t.Fatalf("馆藏>=已借应通过，实际=%v", err)
	}
	if err := checkTotalQty(2, 3); err == nil {
		t.Fatal("馆藏小于已借应拒绝")
	}
}

func TestCalcFine(t *testing.T) {
	today := time.Now()
	due := today.AddDate(0, 0, -10).Format(dateLayout)
	ret := today.Format(dateLayout)
	fine := calcFine(due, ret)
	if fine != 10*FinePerDay {
		t.Fatalf("逾期10天罚款期望 %.1f，实际 %.1f", 10*FinePerDay, fine)
	}
	// 未逾期
	due2 := today.AddDate(0, 0, 5).Format(dateLayout)
	if f := calcFine(due2, ret); f != 0 {
		t.Fatalf("未逾期罚款应为0，实际 %.1f", f)
	}
}

func TestStateText(t *testing.T) {
	now := time.Now()
	// 已归还
	r := modelBorrow("returned", now.AddDate(0, 0, 5).Format(dateLayout))
	if got := stateText(r, now); got != "已归还" {
		t.Fatalf("已归还状态错误：%s", got)
	}
	// 逾期
	r2 := modelBorrow("borrowed", now.AddDate(0, 0, -7).Format(dateLayout))
	if got := stateText(r2, now); got != "已逾期 7 天" {
		t.Fatalf("逾期状态错误：%s", got)
	}
	// 借阅中
	r3 := modelBorrow("borrowed", now.AddDate(0, 0, 12).Format(dateLayout))
	if got := stateText(r3, now); got != "借阅中（剩 12 天）" {
		t.Fatalf("借阅中状态错误：%s", got)
	}
}

func modelBorrow(status, due string) models.BorrowRecord {
	return models.BorrowRecord{Status: status, DueDate: due}
}

